	type ReactNode,
	useCallback,
	useContext,
	useEffect,
	useRef,
	useState,
} from "react";
import { createRoot } from "react-dom/client";
import {
	approvalCapabilityFromMeta,
	persistOpenAiViewSnapshot,
	readOpenAiCompatSnapshot,
} from "./openai-compat";
import { isExternalHttpUrl } from "./view";

/** Shared iframe-side runtime for every Lobu MCP App bundle. */

type ToolArgs = Record<string, unknown>;
type ViewStateValue = boolean | number | string;
type McpAppViewState = Record<string, ViewStateValue>;

interface McpAppApi<T> {
	/** Server-authored LobuViewV1 from the originating tool result. */
	data: T | null;
	/** Originating MCP tool name, supplied by the standard host context. */
	toolName: string | null;
	/** Small restored pagination/disclosure state for this exact result card. */
	viewState: McpAppViewState;
	setViewState: (key: string, value: ViewStateValue) => void;
	/** Ask the host to broker a standard MCP `tools/call`. */
	callTool: (name: string, args: ToolArgs) => Promise<void>;
	/** Ask the host to open an external URL via `ui/open-link`. */
	openLink: (href: string) => Promise<void>;
	/** Latest app-initiated tool result; `seq` bumps so effects react to retries. */
	lastResult: { isError: boolean; seq: number } | null;
	/** True only inside Lobu's same-origin SPA parent, never in an external host. */
	allowSpaHostedViews: boolean;
}

const McpAppContext = createContext<McpAppApi<unknown>>({
	data: null,
	toolName: null,
	viewState: {},
	setViewState: () => {},
	callTool: async () => {},
	openLink: async () => {},
	lastResult: null,
	allowSpaHostedViews: false,
});

/** Typed accessor for the host bridge inside a bundle's card component. */
export function useMcpApp<T>(): McpAppApi<T> {
	return useContext(McpAppContext) as McpAppApi<T>;
}

const isEmbedded = window.parent !== window;
const OPENAI_SET_GLOBALS_EVENT = "openai:set_globals";

type OpenAiCompatWindow = Window & { openai?: unknown };
type OpenAiSetGlobalsEvent = CustomEvent<{ globals?: unknown }>;

function openAiCompatTargets(): OpenAiCompatWindow[] {
	const ownWindow = window as OpenAiCompatWindow;
	if (!isEmbedded) return [ownWindow];
	try {
		if (window.parent.location.origin === window.location.origin) {
			return [ownWindow, window.parent as OpenAiCompatWindow];
		}
	} catch {
		// A cross-origin parent is the standard portable MCP Apps topology.
	}
	return [ownWindow];
}

function currentOpenAiGlobals(targets = openAiCompatTargets()): unknown {
	let fallback: unknown;
	let metadataFallback: unknown;
	let widgetStateFallback: unknown;
	for (const target of targets) {
		const candidate = target.openai;
		if (candidate === undefined) continue;
		fallback ??= candidate;
		if (
			isStructuredObject(candidate) &&
			Object.hasOwn(candidate, "toolOutput")
		) {
			return candidate;
		}
		if (
			isStructuredObject(candidate) &&
			readOpenAiCompatSnapshot(candidate).data !== undefined
		) {
			widgetStateFallback ??= candidate;
		}
		if (
			isStructuredObject(candidate) &&
			Object.hasOwn(candidate, "toolResponseMetadata")
		) {
			metadataFallback ??= candidate;
		}
	}
	return widgetStateFallback ?? metadataFallback ?? fallback;
}

function persistOpenAiData<T>(
	targets: OpenAiCompatWindow[],
	data: T | null,
): void {
	for (const target of targets) {
		if (persistOpenAiViewSnapshot(target.openai, data)) return;
	}
}

function hasSameOriginParent(): boolean {
	if (!isEmbedded) return true;
	try {
		return window.parent.location.origin === window.location.origin;
	} catch {
		return false;
	}
}

function isStructuredObject(value: unknown): value is Record<string, unknown> {
	return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function hasResultData(value: unknown): value is Record<string, unknown> {
	return isStructuredObject(value) && Object.keys(value).length > 0;
}

function toolInfoFromHostContext(value: unknown): {
	id: string | number;
	name: string;
} | null {
	if (!isStructuredObject(value) || !isStructuredObject(value.toolInfo))
		return null;
	const id = value.toolInfo.id;
	const tool = value.toolInfo.tool;
	if (
		(typeof id !== "string" && typeof id !== "number") ||
		!isStructuredObject(tool) ||
		typeof tool.name !== "string"
	) {
		return null;
	}
	return { id, name: tool.name };
}

function snapshotCapabilityFromMeta(value: unknown): string | null {
	if (!isStructuredObject(value)) return null;
	const capability = value["lobu/mcp-app-snapshot-capability"];
	if (typeof capability !== "string") return null;
	const normalized = capability.trim();
	return normalized && normalized.length <= 512 ? normalized : null;
}

function restoredViewState(value: unknown): McpAppViewState {
	if (!isStructuredObject(value)) return {};
	return Object.fromEntries(
		Object.entries(value).filter(
			(entry): entry is [string, ViewStateValue] =>
				typeof entry[1] === "boolean" ||
				typeof entry[1] === "string" ||
				(typeof entry[1] === "number" && Number.isFinite(entry[1])),
		),
	);
}

function applyTheme(theme: "light" | "dark" | undefined): void {
	const dark = theme
		? theme === "dark"
		: window.matchMedia("(prefers-color-scheme: dark)").matches;
	document.documentElement.classList.toggle("dark", dark);
}

export function Provider<T>({
	devMock,
	children,
}: {
	devMock: T;
	children: ReactNode;
}) {
	const [initialCompat] = useState(() =>
		readOpenAiCompatSnapshot<T>(currentOpenAiGlobals()),
	);
	const [data, setData] = useState<T | null>(
		isEmbedded ? (initialCompat.data ?? null) : devMock,
	);
	const [toolName, setToolName] = useState<string | null>(null);
	const [viewState, setViewStateValue] = useState<McpAppViewState>({});
	const [lastResult, setLastResult] = useState<{
		isError: boolean;
		seq: number;
	} | null>(null);
	const [app, setApp] = useState<App | null>(null);
	const [approvalCapability, setApprovalCapability] = useState<string | null>(
		initialCompat.approvalCapability ?? null,
	);
	const hasLiveToolOutput = useRef(false);
	const hasData = useRef(data !== null);
	const toolCallId = useRef<string | number | null>(null);
	const toolCallName = useRef<string | null>(null);
	const snapshotCapability = useRef<string | null>(null);
	const snapshotSaveInFlight = useRef(false);
	const snapshotRestore = useRef<string | null>(null);
	const viewStateRef = useRef<McpAppViewState>({});
	const viewStateRevision = useRef(0);
	const persistSnapshotStateRef = useRef<(() => void) | null>(null);
	const saveStateTimer = useRef<number | null>(null);
	const allowSpaHostedViews = hasSameOriginParent();

	useEffect(() => {
		if (!isEmbedded) {
			applyTheme(undefined);
			return;
		}

		const compatTargets = openAiCompatTargets();
		const nextApp = new App(
			{ name: "Lobu Interaction", version: "1.0.0" },
			{},
			{ autoResize: true, strict: true },
		);
		const transport = new PostMessageTransport(window.parent, window.parent);
		const persistSnapshotState = async () => {
			const capability = snapshotCapability.current;
			const id = toolCallId.current;
			const name = toolCallName.current;
			const revision = viewStateRevision.current;
			if ((id === null && !capability) || snapshotSaveInFlight.current) return;
			snapshotSaveInFlight.current = true;
			try {
				const result = await nextApp.callServerTool({
					name: "save_lobu_app_state",
					arguments: {
						...(id === null ? {} : { tool_call_id: id }),
						...(name ? { tool_name: name } : {}),
						view_state: viewStateRef.current,
						...(capability ? { snapshot_capability: capability } : {}),
					},
					...(capability
						? {
								_meta: {
									"lobu/mcp-app-snapshot-capability": capability,
								},
							}
						: {}),
				});
				if (
					capability &&
					id !== null &&
					result.isError !== true &&
					isStructuredObject(result.structuredContent) &&
					result.structuredContent.saved === true &&
					snapshotCapability.current === capability &&
					toolCallId.current === id &&
					toolCallName.current === name &&
					viewStateRevision.current === revision
				) {
					// A standard host card id is sufficient for later state writes. Hosts
					// without toolInfo keep the scoped capability in iframe memory.
