				snapshotSaveInFlight.current = false;
				if (
					(toolCallId.current !== null || snapshotCapability.current) &&
					(snapshotCapability.current !== capability ||
						toolCallId.current !== id ||
						toolCallName.current !== name ||
						viewStateRevision.current !== revision)
				) {
					// Result metadata, host identity, and UI state can change in either order.
					// Serialize them, then retry only the newest state after this save settles.
					void persistSnapshotState();
				}
			}
		};
		persistSnapshotStateRef.current = () => void persistSnapshotState();
		const restoreSnapshot = async () => {
			if (hasData.current) return;
			const capability = snapshotCapability.current;
			const id = toolCallId.current;
			const name = toolCallName.current;
			if (id === null && !capability) return;
			const restoreKey = `${id ?? "capability"}:${capability ?? ""}`;
			if (snapshotRestore.current === restoreKey) return;
			snapshotRestore.current = restoreKey;
			try {
				const result = await nextApp.callServerTool({
					name: "restore_lobu_app_result",
					arguments: {
						...(id === null ? {} : { tool_call_id: id }),
						...(name ? { tool_name: name } : {}),
						...(capability ? { snapshot_capability: capability } : {}),
					},
				});
