/**
 * Read ChatGPT's compatibility globals without making them a dependency of the
 * portable MCP Apps bridge. ChatGPT restores these globals for historical
 * cards, including after the standard tool-result notification has already
 * happened in an earlier page lifetime.
 */
export function readOpenAiCompatSnapshot<T>(
	globals: unknown,
): OpenAiCompatSnapshot<T> {
	if (!isStructuredObject(globals)) {
		return { data: undefined, approvalCapability: undefined };
	}

	const hasToolOutput = Object.hasOwn(globals, "toolOutput");
	const hasFullToolResult =
		hasToolOutput &&
		isStructuredObject(globals.toolOutput) &&
		Object.hasOwn(globals.toolOutput, "structuredContent");
	const outputData = hasToolOutput
		? dataFromToolOutput<T>(globals.toolOutput)
		: dataFromWidgetState<T>(globals.widgetState);
	const hasToolResponseMetadata = Object.hasOwn(
		globals,
		"toolResponseMetadata",
	);
	const metadata = isStructuredObject(globals.toolResponseMetadata)
		? globals.toolResponseMetadata
		: null;
	const approvalCapability = hasToolResponseMetadata
		? metadata
			? (approvalCapabilityFromResult(metadata.mcp_tool_result) ??
				approvalCapabilityFromResult(metadata.call_tool_result))
			: null
		: hasFullToolResult
			? approvalCapabilityFromResult(globals.toolOutput)
			: undefined;
	const data =
		hasToolOutput && approvalCapability === null
			? displaySafeSnapshotData(outputData)
			: outputData;

	return { data, approvalCapability };
}
